"""Application configuration: dataclasses with tolerant JSON load/save.

The file lives at ``data/config.json`` and is created with defaults on first
use. Unknown keys are ignored and missing keys fall back to their defaults, so
older or hand-edited files keep working. Standard library only (the optional
ML tooling imports this module too).
"""

from __future__ import annotations

import json
import os
from dataclasses import asdict, dataclass, field, fields
from pathlib import Path
from typing import Any, Optional

PROJECT_ROOT = Path(__file__).resolve().parents[1]
DATA_DIR = PROJECT_ROOT / "data"
DEFAULT_CONFIG_PATH = DATA_DIR / "config.json"


@dataclass
class ProcessingConfig:
    """Signal processing parameters (see :mod:`backend.processing`)."""

    #: Sliding analysis window, seconds of host time.
    window_s: float = 1.0
    #: Hampel filter history length (packets) and threshold (scaled MADs).
    hampel_window: int = 7
    hampel_k: float = 3.0
    #: EMA smoothing factor per packet (1.0 = no smoothing).
    ema_alpha: float = 0.3
    #: Time constant of the slow adaptive reference profile used when no
    #: calibration baseline is set.
    reference_tau_s: float = 30.0
    #: Frames (motion feature snapshots) emitted per second of packet time.
    frame_rate_hz: float = 10.0
    #: Data-quality gates: below these a frame is flagged insufficient.
    min_packet_rate_hz: float = 20.0
    min_window_fill: float = 0.7
    stale_after_s: float = 1.0
    #: Noise references used to normalise the motion score while uncalibrated.
    #: Calibration (Milestone 3) replaces them with measured empty-room values.
    uncalibrated_variance_ref: float = 0.03
    uncalibrated_diff_ref: float = 0.01


@dataclass
class MotionThresholds:
    """Motion score thresholds. Calibrated empty room scores about 1.0.

    * score < ``movement``          -> empty room / low activity
    * ``movement`` <= score < ``rapid`` -> movement detected
    * score >= ``rapid``            -> rapid movement
    * ``low`` marks "still" (used later for post-event stillness checks)

    The defaults are uncalibrated guesses, not measured values.
    """

    low: float = 1.5
    movement: float = 2.5
    rapid: float = 6.0
    calibrated: bool = False


@dataclass
class AppConfig:
    processing: ProcessingConfig = field(default_factory=ProcessingConfig)
    thresholds: MotionThresholds = field(default_factory=MotionThresholds)

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: Optional[dict]) -> "AppConfig":
        data = data if isinstance(data, dict) else {}
        return cls(
            processing=_build(ProcessingConfig, data.get("processing")),
            thresholds=_build(MotionThresholds, data.get("thresholds")),
        )

    def save(self, path=DEFAULT_CONFIG_PATH) -> Path:
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        tmp = path.with_suffix(path.suffix + ".tmp")
        tmp.write_text(json.dumps(self.to_dict(), indent=2) + "\n", encoding="utf-8")
        os.replace(tmp, path)
        return path

    @classmethod
    def load(cls, path=DEFAULT_CONFIG_PATH) -> "AppConfig":
        """Load ``path``; raises ``FileNotFoundError`` / ``ValueError`` on problems."""
        text = Path(path).read_text(encoding="utf-8")
        try:
            data = json.loads(text)
        except json.JSONDecodeError as e:
            raise ValueError(f"{path}: invalid JSON ({e})") from None
        return cls.from_dict(data)

    @classmethod
    def load_or_create(cls, path=DEFAULT_CONFIG_PATH) -> "AppConfig":
        """Load ``path``, creating it with defaults if it does not exist."""
        path = Path(path)
        if not path.exists():
            cfg = cls()
            cfg.save(path)
            return cfg
        return cls.load(path)


def _build(dc_type, data: Any):
    """Instantiate ``dc_type`` from a dict, ignoring unknown keys and keeping
    defaults for missing or wrongly typed values."""
    obj = dc_type()
    if not isinstance(data, dict):
        return obj
    for f in fields(dc_type):
        if f.name not in data:
            continue
        default = getattr(obj, f.name)
        value = data[f.name]
        try:
            if isinstance(default, bool):
                if isinstance(value, bool):
                    setattr(obj, f.name, value)
            elif isinstance(default, int):
                setattr(obj, f.name, int(value))
            elif isinstance(default, float):
                setattr(obj, f.name, float(value))
            else:
                setattr(obj, f.name, value)
        except (TypeError, ValueError):
            pass
    return obj

"""Flask app serving the EchoGuard dashboard and its JSON API.

The UI is a self-contained single page in ``dashboard/static`` (vanilla JS,
canvas charts, no CDN). The server has **no authentication**: it binds to
127.0.0.1 by default and must not be exposed on a shared network.

Routes::

    GET  /                       dashboard page
    GET  /api/status             Engine.snapshot()
    GET  /api/series?seconds=30  motion feature time series
    GET  /api/heatmap?n=300      normalised subcarrier amplitude rows
    GET  /api/ports              serial port candidates (read-only listing)
    GET  /api/replay_files       recordings and fixtures that can be replayed
    POST /api/source             {"kind": "serial", "port": "auto"|"/dev/...", "baud": 921600}
                                 {"kind": "replay", "path": "...", "speed": 1.0, "loop": false}
    POST /api/stop               stop the current source
"""

from __future__ import annotations

import logging
import re
from pathlib import Path
from typing import Iterable, Optional

from flask import Flask, jsonify, request, send_from_directory

from backend.engine import Engine
from backend.ports import list_candidates
from backend.sources import ReplaySource, SerialSource

log = logging.getLogger(__name__)

PROJECT_ROOT = Path(__file__).resolve().parents[1]
STATIC_DIR = Path(__file__).resolve().parent / "static"
REPLAY_EXTENSIONS = (".csv", ".txt", ".log")
FIXTURE_EXTENSIONS = (".csv", ".txt")
#: Serial device paths: /dev/ followed by safe path segments (no '..').
PORT_RE = re.compile(r"^/dev/[A-Za-z0-9_.\-]+(/[A-Za-z0-9_.\-]+)*$")
BAUD_MIN, BAUD_MAX = 9600, 3_000_000
SPEED_MAX = 50.0
LINE_RATE_MIN, LINE_RATE_MAX = 1.0, 2000.0
SERIES_MAX_S = 120.0
HEATMAP_MAX_N = 600

CSP = ("default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; "
       "connect-src 'self'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'")


class BadRequest(ValueError):
    """Input validation failure, reported as HTTP 400 with a JSON error."""


def _err(message: str, status: int = 400):
    return jsonify({"ok": False, "error": message}), status


def _num(value, name: str, lo: float, hi: float, default=None, integer: bool = False):
    if value is None:
        if default is None:
            raise BadRequest(f"'{name}' is required")
        return default
    if isinstance(value, bool):
        raise BadRequest(f"'{name}' must be a number")
    try:
        num = int(value) if integer else float(value)
    except (TypeError, ValueError):
        raise BadRequest(f"'{name}' must be {'an integer' if integer else 'a number'}") from None
    if integer and isinstance(value, float) and not value.is_integer():
        raise BadRequest(f"'{name}' must be an integer")
    if not (lo <= num <= hi) or num != num:
        raise BadRequest(f"'{name}' must be between {lo:g} and {hi:g}")
    return num


def validate_port(port) -> str:
    if not isinstance(port, str) or not port:
        raise BadRequest("'port' must be 'auto' or a /dev/ device path")
    if port == "auto":
        return port
    if not PORT_RE.match(port) or ".." in port.split("/"):
        raise BadRequest("'port' must be 'auto' or a /dev/ device path such as /dev/cu.usbmodem1101")
    return port


def resolve_replay_path(path, root: Path, allowed_dirs: Iterable[Path]) -> Path:
    """Resolve ``path`` (relative to ``root`` or absolute) and require it to be
    an existing replayable file inside one of ``allowed_dirs``."""
    if not isinstance(path, str) or not path.strip() or "\x00" in path:
        raise BadRequest("'path' must be a non-empty string")
    p = Path(path)
    if not p.is_absolute():
        p = root / p
    try:
        resolved = p.resolve(strict=False)
    except (OSError, RuntimeError):
        raise BadRequest("invalid path") from None
    if not any(resolved.is_relative_to(d.resolve()) for d in allowed_dirs):
        raise BadRequest("replay files must be inside data/ or tests/fixtures/")
    if resolved.suffix.lower() not in REPLAY_EXTENSIONS:
        raise BadRequest(f"replay files must be one of {', '.join(REPLAY_EXTENSIONS)}")
    if not resolved.is_file():
        raise BadRequest("replay file not found")
    return resolved


def list_replay_files(root: Path) -> list:
    out = []
    rec_dir = root / "data" / "recordings"
    if rec_dir.is_dir():
        for p in sorted(rec_dir.rglob("*")):
            if p.is_file() and p.suffix.lower() in REPLAY_EXTENSIONS:
                out.append(_file_entry(p, root, "recordings"))
    fix_dir = root / "tests" / "fixtures"
    if fix_dir.is_dir():
        for p in sorted(fix_dir.iterdir()):
            if p.is_file() and p.suffix.lower() in FIXTURE_EXTENSIONS:
                out.append(_file_entry(p, root, "fixtures"))
    return out


def _file_entry(p: Path, root: Path, group: str) -> dict:
    try:
        size = p.stat().st_size
    except OSError:
        size = None
    return {"path": p.relative_to(root).as_posix(), "name": p.name, "group": group, "size": size}


def create_app(engine: Engine, root: Optional[Path] = None, replay_dirs: Optional[list] = None) -> Flask:
    """Flask app factory. ``root`` / ``replay_dirs`` are overridable for tests."""
    root = Path(root or PROJECT_ROOT).resolve()
    allowed = [Path(d).resolve() for d in (replay_dirs or [root / "data", root / "tests" / "fixtures"])]

    app = Flask(__name__, static_folder=str(STATIC_DIR), static_url_path="/static")
    app.config["ENGINE"] = engine
    app.json.sort_keys = False

    @app.after_request
    def _headers(resp):
        resp.headers["X-Content-Type-Options"] = "nosniff"
        resp.headers["Content-Security-Policy"] = CSP
        resp.headers["Referrer-Policy"] = "no-referrer"
        if request.path.startswith("/api/"):
            resp.headers["Cache-Control"] = "no-store"
        return resp

    @app.errorhandler(BadRequest)
    def _bad_request(e):
        return _err(str(e), 400)

    @app.errorhandler(404)
    def _not_found(e):
        if request.path.startswith("/api/"):
            return _err("not found", 404)
        return e

    @app.errorhandler(405)
    def _not_allowed(e):
        if request.path.startswith("/api/"):
            return _err("method not allowed", 405)
        return e

    @app.errorhandler(500)
    def _server_error(e):
        log.exception("internal error")
        return _err("internal server error", 500)

    @app.get("/")
    def index():
        return send_from_directory(STATIC_DIR, "index.html")

    @app.get("/api/status")
    def status():
        return jsonify(engine.snapshot())

    @app.get("/api/series")
    def series():
        seconds = _num(request.args.get("seconds"), "seconds", 1, SERIES_MAX_S, default=30.0)
        return jsonify(engine.series(seconds))

    @app.get("/api/heatmap")
    def heatmap():
        n = _num(request.args.get("n"), "n", 1, HEATMAP_MAX_N, default=300, integer=True)
        return jsonify(engine.heatmap(n))

    @app.get("/api/ports")
    def ports():
        try:
            cands = list_candidates()
        except Exception as e:  # noqa: BLE001
            return jsonify({"ports": [], "error": f"could not list serial ports: {e}"})
        return jsonify({"ports": [{
            "device": c.device, "description": c.description, "vid_pid": c.vid_pid,
            "likely_esp32": c.likely_esp32, "excluded": c.excluded, "bridge": c.bridge, "reason": c.reason,
        } for c in cands], "error": None})

    @app.get("/api/replay_files")
    def replay_files():
        return jsonify({"files": list_replay_files(root)})

    @app.post("/api/source")
    def set_source():
        if not request.is_json:
            raise BadRequest("expected a JSON body (Content-Type: application/json)")
        body = request.get_json(silent=True)
        if not isinstance(body, dict):
            raise BadRequest("expected a JSON object")
        kind = body.get("kind")
        if kind == "serial":
            port = validate_port(body.get("port", "auto"))
            baud = _num(body.get("baud"), "baud", BAUD_MIN, BAUD_MAX, default=921600, integer=True)
            source = SerialSource(port, baud=baud)
        elif kind == "replay":
            path = resolve_replay_path(body.get("path"), root, allowed)
            speed = _num(body.get("speed"), "speed", 0.0, SPEED_MAX, default=1.0)
            line_rate = _num(body.get("line_rate_hz"), "line_rate_hz", LINE_RATE_MIN, LINE_RATE_MAX, default=100.0)
            loop = body.get("loop", False)
            if not isinstance(loop, bool):
                raise BadRequest("'loop' must be true or false")
            try:
                source = ReplaySource(path, speed=speed, loop=loop, line_rate_hz=line_rate)
            except OSError as e:
                raise BadRequest(f"cannot open replay file: {e.strerror or e}") from None
        elif kind == "simulation":
            raise BadRequest("simulation mode is not available yet (planned for Milestone 5)")
        else:
            raise BadRequest("'kind' must be 'serial' or 'replay'")
        engine.start(source)
        return jsonify({"ok": True, "status": engine.snapshot()})

    @app.post("/api/stop")
    def stop():
        engine.stop()
        return jsonify({"ok": True, "status": engine.snapshot()})

    return app

/* EchoGuard dashboard - dark theme, no external assets. */
:root {
  --bg: #0b0f17;
  --bg-elev: #121826;
  --card: #151c2c;
  --card-border: #232c42;
  --text: #e6eaf2;
  --muted: #9aa5bd;
  --accent: #5ab0ff;
  --ok: #3ddc97;
  --warn: #ffb547;
  --bad: #ff5d6c;
  --sim: #d27bff;
  --empty: #3ddc97;
  --move: #5ab0ff;
  --rapid: #ffb547;
  --fall: #ff5d6c;
  --unknown: #6b7590;
  --radius: 12px;
  --mono: ui-monospace, SFMono-Regular, Menlo, Consolas, "Liberation Mono", monospace;
  --sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; background: var(--bg); color: var(--text); font-family: var(--sans); font-size: 15px; line-height: 1.4; }
h1, h2, h3 { margin: 0; font-weight: 600; }
h1 { font-size: 1.35rem; letter-spacing: 0.02em; }
h2 { font-size: 1.05rem; }
h3 { font-size: 0.85rem; color: var(--muted); text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 0.5rem; }
.mono { font-family: var(--mono); font-variant-numeric: tabular-nums; }
.muted { color: var(--muted); }
.small { font-size: 0.8rem; }
.wrap { word-break: break-word; white-space: normal; }
.hidden { display: none !important; }

.skip-link { position: absolute; left: -999px; top: 0; background: var(--accent); color: #000; padding: 0.4rem 0.8rem; z-index: 10; }
.skip-link:focus { left: 0.5rem; }

.topbar { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.9rem 1.5rem; background: var(--bg-elev); border-bottom: 1px solid var(--card-border); position: sticky; top: 0; z-index: 5; }
.brand { display: flex; align-items: center; gap: 0.75rem; }
.brand-mark { width: 30px; height: 30px; border-radius: 50%; background: radial-gradient(circle at 50% 50%, var(--accent) 0 20%, transparent 21% 36%, rgba(90,176,255,0.6) 37% 46%, transparent 47% 62%, rgba(90,176,255,0.3) 63% 72%, transparent 73%); }
.tagline { margin: 0; color: var(--muted); font-size: 0.8rem; }
.topbar-status { display: flex; gap: 0.5rem; flex-wrap: wrap; }

.pill { display: inline-block; padding: 0.2rem 0.7rem; border-radius: 999px; font-size: 0.8rem; border: 1px solid var(--card-border); background: var(--card); }
.pill-ok { color: var(--ok); border-color: rgba(61,220,151,0.5); }
.pill-warn { color: var(--warn); border-color: rgba(255,181,71,0.5); }
.pill-bad { color: var(--bad); border-color: rgba(255,93,108,0.5); }
.pill-muted { color: var(--muted); }

.banner { margin: 0; padding: 0.7rem 1.5rem; font-weight: 700; letter-spacing: 0.05em; text-align: center; }
.banner-replay { background: rgba(255,181,71,0.16); color: var(--warn); border-bottom: 1px solid rgba(255,181,71,0.5); }
.banner-sim { background: rgba(210,123,255,0.18); color: var(--sim); border-bottom: 2px solid var(--sim); font-size: 1.05rem; }

main { padding: 1.25rem 1.5rem 2rem; max-width: 1500px; margin: 0 auto; display: flex; flex-direction: column; gap: 1.25rem; }
.section-title { margin-bottom: 0.6rem; }
.grid { display: grid; gap: 1rem; }
.status-grid { grid-template-columns: repeat(auto-fit, minmax(230px, 1fr)); }
.chart-grid { grid-template-columns: repeat(auto-fit, minmax(420px, 1fr)); }
.wide { grid-column: 1 / -1; }

.card { background: var(--card); border: 1px solid var(--card-border); border-radius: var(--radius); padding: 1rem 1.1rem; }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; margin-bottom: 0.6rem; }
.card-head h3 { margin-bottom: 0; }
.big { font-size: 1.6rem; font-weight: 600; margin: 0.1rem 0 0.6rem; }

.kv { display: grid; grid-template-columns: auto 1fr; gap: 0.25rem 0.8rem; margin: 0; font-size: 0.85rem; }
.kv dt { color: var(--muted); }
.kv dd { margin: 0; text-align: right; }
.kv-cols { grid-template-columns: repeat(auto-fit, minmax(110px, auto) minmax(120px, 1fr)); }
.kv-cols dd { text-align: left; }
.kv-inline { grid-template-columns: auto auto; }

.badge { display: inline-block; padding: 0.3rem 0.8rem; border-radius: 8px; font-weight: 700; font-size: 0.9rem; }
.badge-ok { background: rgba(61,220,151,0.15); color: var(--ok); }
.badge-bad { background: rgba(255,93,108,0.15); color: var(--bad); }
.badge-muted { background: rgba(107,117,144,0.2); color: var(--muted); }
.reasons { margin: 0.6rem 0 0; padding-left: 1.1rem; font-size: 0.8rem; color: var(--muted); }

.controls .control-row { display: flex; align-items: center; gap: 0.6rem; flex-wrap: wrap; }
.control-foot { margin-top: 0.8rem; padding-top: 0.8rem; border-top: 1px solid var(--card-border); }
label { color: var(--muted); font-size: 0.85rem; }
label.check { display: inline-flex; align-items: center; gap: 0.35rem; }
select, input[type="number"] { background: var(--bg); color: var(--text); border: 1px solid var(--card-border); border-radius: 8px; padding: 0.4rem 0.55rem; font-family: var(--mono); font-size: 0.85rem; }
select { min-width: 220px; max-width: 420px; }
input[type="number"] { width: 110px; }
.tabs { display: flex; gap: 0.3rem; }
.tab { background: transparent; color: var(--muted); border: 1px solid var(--card-border); border-radius: 8px; padding: 0.35rem 0.8rem; cursor: pointer; font-size: 0.85rem; }
.tab.active { color: var(--text); border-color: var(--accent); background: rgba(90,176,255,0.12); }
.btn { border-radius: 8px; border: 1px solid var(--card-border); padding: 0.42rem 0.95rem; font-size: 0.85rem; font-weight: 600; cursor: pointer; color: var(--text); background: var(--bg-elev); }
.btn:hover { filter: brightness(1.15); }
.btn:disabled { opacity: 0.5; cursor: not-allowed; }
.btn-primary { background: #1f6fd1; border-color: #2f80e6; }
.btn-danger { background: rgba(255,93,108,0.15); border-color: rgba(255,93,108,0.6); color: #ffc2c8; }
.btn-ghost { background: transparent; }
button:focus-visible, select:focus-visible, input:focus-visible, a:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.activity-card h2 { margin-bottom: 0.8rem; }
.activity-row { display: flex; align-items: center; gap: 1.5rem; flex-wrap: wrap; }
.activity { min-width: 320px; padding: 1.1rem 1.4rem; border-radius: 14px; font-size: 1.5rem; font-weight: 700; text-align: center; border: 2px solid transparent; }
.activity.act-empty_low { background: rgba(61,220,151,0.12); color: var(--empty); border-color: rgba(61,220,151,0.5); }
.activity.act-movement { background: rgba(90,176,255,0.14); color: var(--move); border-color: rgba(90,176,255,0.6); }
.activity.act-rapid_movement { background: rgba(255,181,71,0.14); color: var(--rapid); border-color: rgba(255,181,71,0.6); }
.activity.act-potential_fall { background: rgba(255,93,108,0.2); color: #ffd0d5; border-color: var(--fall); animation: pulse 1s ease-in-out infinite; }
.activity.act-unknown { background: rgba(107,117,144,0.15); color: var(--muted); border-color: rgba(107,117,144,0.4); }
@keyframes pulse { 0%, 100% { box-shadow: 0 0 0 0 rgba(255,93,108,0.6); } 50% { box-shadow: 0 0 0 10px rgba(255,93,108,0); } }
@media (prefers-reduced-motion: reduce) { .activity.act-potential_fall { animation: none; } }
.legend-states { display: flex; flex-wrap: wrap; gap: 0.4rem 1.2rem; list-style: none; padding: 0; margin: 1rem 0 0.4rem; font-size: 0.8rem; color: var(--muted); }
.dot { display: inline-block; width: 10px; height: 10px; border-radius: 50%; margin-right: 0.4rem; vertical-align: middle; }
.dot.act-empty_low { background: var(--empty); }
.dot.act-movement { background: var(--move); }
.dot.act-rapid_movement { background: var(--rapid); }
.dot.act-potential_fall { background: var(--fall); }
.dot.act-unknown { background: var(--unknown); }

.chart canvas { display: block; width: 100%; border-radius: 8px; background: #0e1420; }
.canvas-heat { height: 260px; }
.canvas-line { height: 180px; }
.legend-scale { display: flex; align-items: center; gap: 0.4rem; }
#heat-legend { width: 160px; height: 12px; border-radius: 3px; }

.footer { border-top: 1px solid var(--card-border); padding: 1rem 1.5rem 1.5rem; text-align: center; background: var(--bg-elev); }
.footer p { margin: 0.2rem 0; }

@media (max-width: 700px) {
  .chart-grid { grid-template-columns: 1fr; }
  .activity { min-width: 0; width: 100%; }
  main { padding: 1rem; }
}

/* EchoGuard dashboard client. Plain ES2017, no dependencies, no network
 * access other than the local backend (same origin). Polls the JSON API and
 * draws charts on <canvas>. Never shows invented values: missing data is
 * rendered as "No data yet" / "-". */
"use strict";

(function () {
  const POLL_MS = 400;          // ~2.5 Hz
  const SERIES_SECONDS = 30;
  const HEATMAP_ROWS = 300;
  const REQUEST_TIMEOUT_MS = 4000;
  const NO_DATA = "No data yet";

  const ACTIVITY_KEYS = ["empty_low", "movement", "rapid_movement", "potential_fall", "unknown"];
  const COLORS = {
    text: "#e6eaf2", muted: "#9aa5bd", grid: "#232c42", accent: "#5ab0ff",
    ok: "#3ddc97", warn: "#ffb547", bad: "#ff5d6c", violet: "#d27bff",
  };

  const $ = (id) => document.getElementById(id);

  // ------------------------------------------------------------ helpers
  async function api(path, options) {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), REQUEST_TIMEOUT_MS);
    const opts = Object.assign({ signal: ctrl.signal, cache: "no-store" }, options || {});
    try {
      const resp = await fetch(path, opts);
      let body = null;
      try { body = await resp.json(); } catch (e) { body = null; }
      if (!resp.ok) {
        const msg = body && body.error ? body.error : "HTTP " + resp.status;
        throw new Error(msg);
      }
      return body;
    } finally {
      clearTimeout(timer);
    }
  }

  function postJSON(path, data) {
    return api(path, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data || {}),
    });
  }

  const isNum = (v) => typeof v === "number" && isFinite(v);

  function fmt(v, digits, unit) {
    if (!isNum(v)) return null;
    const s = v.toFixed(digits === undefined ? 1 : digits);
    return unit ? s + " " + unit : s;
  }

  function setText(id, value, fallback) {
    const el = $(id);
    if (!el) return;
    const text = value === null || value === undefined || value === "" ? (fallback === undefined ? "-" : fallback) : String(value);
    if (el.textContent !== text) el.textContent = text;
  }

  function setClass(el, base, cls) {
    const next = base + " " + cls;
    if (el.className !== next) el.className = next;
  }

  function showMessage(text, isError) {
    const el = $("control-msg");
    el.textContent = text || "";
    el.style.color = isError ? COLORS.bad : "";
  }

  // ------------------------------------------------------------ canvas
  function prepCanvas(canvas) {
    const dpr = window.devicePixelRatio || 1;
    const w = Math.max(10, Math.floor(canvas.clientWidth));
    const h = Math.max(10, Math.floor(canvas.clientHeight));
    if (canvas.width !== Math.floor(w * dpr) || canvas.height !== Math.floor(h * dpr)) {
      canvas.width = Math.floor(w * dpr);
      canvas.height = Math.floor(h * dpr);
    }
    const ctx = canvas.getContext("2d");
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    return { ctx: ctx, w: w, h: h };
  }

  function drawEmpty(ctx, w, h, text) {
    ctx.fillStyle = COLORS.muted;
    ctx.font = "13px -apple-system, Segoe UI, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(text, w / 2, h / 2);
  }

  // Viridis-like colour map (5 stops), precomputed into a 256 entry LUT.
  const CMAP_STOPS = [
    [0.0, [68, 1, 84]], [0.25, [59, 82, 139]], [0.5, [33, 145, 140]],
    [0.75, [94, 201, 98]], [1.0, [253, 231, 37]],
  ];
  const LUT = (function () {
    const lut = new Uint8ClampedArray(256 * 3);
    for (let i = 0; i < 256; i++) {
      const t = i / 255;
      let k = 0;
      while (k < CMAP_STOPS.length - 2 && t > CMAP_STOPS[k + 1][0]) k++;
      const a = CMAP_STOPS[k], b = CMAP_STOPS[k + 1];
      const f = (t - a[0]) / (b[0] - a[0]);
      for (let c = 0; c < 3; c++) lut[i * 3 + c] = a[1][c] + (b[1][c] - a[1][c]) * f;
    }
    return lut;
  })();

  function drawLegend() {
    const canvas = $("heat-legend");
    const ctx = canvas.getContext("2d");
    const img = ctx.createImageData(canvas.width, canvas.height);
    for (let x = 0; x < canvas.width; x++) {
      const i = Math.round((x / (canvas.width - 1)) * 255);
      for (let y = 0; y < canvas.height; y++) {
        const p = (y * canvas.width + x) * 4;
        img.data[p] = LUT[i * 3]; img.data[p + 1] = LUT[i * 3 + 1]; img.data[p + 2] = LUT[i * 3 + 2]; img.data[p + 3] = 255;
      }
    }
    ctx.putImageData(img, 0, 0);
  }

  const heatOffscreen = document.createElement("canvas");

  function drawHeatmap(data) {
    const canvas = $("heatmap");
    const c = prepCanvas(canvas);
    const ctx = c.ctx;
    const rows = data && data.rows ? data.rows : [];
    if (!rows.length) {
      setText("heat-min", null); setText("heat-max", null);
      drawEmpty(ctx, c.w, c.h, NO_DATA + " - waiting for CSI packets");
      return;
    }
    const nT = rows.length;
    const nS = rows[0].length;
    let vmin = isNum(data.vmin) ? data.vmin : 0;
    let vmax = isNum(data.vmax) ? data.vmax : 1;
    if (vmax - vmin < 1e-6) { vmin -= 0.5; vmax += 0.5; }
    setText("heat-min", vmin.toFixed(2)); setText("heat-max", vmax.toFixed(2));

    // time on the x axis (newest at right), subcarrier on the y axis
    heatOffscreen.width = nT; heatOffscreen.height = nS;
    const octx = heatOffscreen.getContext("2d");
    const img = octx.createImageData(nT, nS);
    const span = vmax - vmin;
    for (let t = 0; t < nT; t++) {
      const row = rows[t];
      for (let s = 0; s < nS; s++) {
        const v = row[s];
        const p = ((nS - 1 - s) * nT + t) * 4;
        if (!isNum(v)) {
          img.data[p] = 30; img.data[p + 1] = 34; img.data[p + 2] = 44; img.data[p + 3] = 255;
          continue;
        }
        let i = Math.round(((v - vmin) / span) * 255);
        i = i < 0 ? 0 : (i > 255 ? 255 : i);
        img.data[p] = LUT[i * 3]; img.data[p + 1] = LUT[i * 3 + 1]; img.data[p + 2] = LUT[i * 3 + 2]; img.data[p + 3] = 255;
      }
    }
    octx.putImageData(img, 0, 0);

    const padL = 52, padB = 22, padT = 6, padR = 8;
    const pw = c.w - padL - padR, ph = c.h - padT - padB;
    // keep a fixed time scale: fewer rows than HEATMAP_ROWS fill from the right
    const drawW = Math.max(1, Math.round(pw * Math.min(1, nT / HEATMAP_ROWS)));
    ctx.imageSmoothingEnabled = false;
    ctx.fillStyle = "#0e1420";
    ctx.fillRect(padL, padT, pw, ph);
    ctx.drawImage(heatOffscreen, padL + pw - drawW, padT, drawW, ph);

    ctx.fillStyle = COLORS.muted;
    ctx.font = "11px " + getComputedStyle(document.body).getPropertyValue("--mono");
    ctx.textAlign = "right";
    ctx.textBaseline = "middle";
    const labels = data.labels || [];
    if (labels.length) {
      ctx.fillText(labels[labels.length - 1], padL - 4, padT + 6);
      ctx.fillText(labels[0], padL - 4, padT + ph - 6);
    }
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(nT + " packets, " + nS + " subcarriers", padL, padT + ph + 5);
    ctx.textAlign = "right";
    ctx.fillText("newest", padL + pw, padT + ph + 5);
  }

  /* Generic time-series line chart.
   * opts: {ts, tEnd, seconds, series: [{values, color, label}], thresholds: [{value, color, label}],
   *        unit, digits, minRange, zeroBased} */
  function drawLineChart(canvas, opts) {
    const c = prepCanvas(canvas);
    const ctx = c.ctx;
    const ts = opts.ts || [];
    const padL = 52, padR = 10, padT = 10, padB = 22;
    const pw = c.w - padL - padR, ph = c.h - padT - padB;

    let lo = Infinity, hi = -Infinity, count = 0;
    opts.series.forEach((s) => s.values.forEach((v) => {
      if (isNum(v)) { lo = Math.min(lo, v); hi = Math.max(hi, v); count++; }
    }));
    if (!ts.length || !count) {
      drawEmpty(ctx, c.w, c.h, NO_DATA);
      return;
    }
    (opts.thresholds || []).forEach((t) => {
      if (isNum(t.value)) { lo = Math.min(lo, t.value); hi = Math.max(hi, t.value); }
    });
    if (opts.zeroBased) lo = Math.min(0, lo);
    const minRange = opts.minRange || 1e-3;
    if (hi - lo < minRange) { const mid = (hi + lo) / 2; lo = mid - minRange / 2; hi = mid + minRange / 2; }
    const padY = (hi - lo) * 0.08;
    hi += padY; if (!opts.zeroBased || lo < 0) lo -= padY;

    const tEnd = isNum(opts.tEnd) ? opts.tEnd : ts[ts.length - 1];
    const seconds = opts.seconds || SERIES_SECONDS;
    const x = (t) => padL + pw * (1 - (tEnd - t) / seconds);
    const y = (v) => padT + ph * (1 - (v - lo) / (hi - lo));

    // grid + y labels
    ctx.strokeStyle = COLORS.grid; ctx.lineWidth = 1;
    ctx.fillStyle = COLORS.muted;
    ctx.font = "11px " + getComputedStyle(document.body).getPropertyValue("--mono");
    ctx.textAlign = "right"; ctx.textBaseline = "middle";
    const digits = opts.digits === undefined ? 2 : opts.digits;
    for (let i = 0; i <= 4; i++) {
      const v = lo + (hi - lo) * (i / 4);
      const yy = Math.round(y(v)) + 0.5;
      ctx.beginPath(); ctx.moveTo(padL, yy); ctx.lineTo(padL + pw, yy); ctx.stroke();
      ctx.fillText(v.toFixed(digits), padL - 5, yy);
    }
    ctx.textAlign = "center"; ctx.textBaseline = "top";
    for (let s = 0; s <= seconds; s += Math.max(5, Math.round(seconds / 6))) {
      const xx = x(tEnd - s);
      ctx.fillText(s === 0 ? "now" : "-" + s + "s", xx, padT + ph + 5);
    }

    // thresholds
    (opts.thresholds || []).forEach((t) => {
      if (!isNum(t.value)) return;
      const yy = Math.round(y(t.value)) + 0.5;
      ctx.save();
      ctx.setLineDash([5, 4]);
      ctx.strokeStyle = t.color; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(padL, yy); ctx.lineTo(padL + pw, yy); ctx.stroke();
      ctx.restore();
      ctx.fillStyle = t.color; ctx.textAlign = "left"; ctx.textBaseline = "bottom";
      ctx.fillText(t.label, padL + 4, yy - 2);
    });

    // series (gaps where values are null)
    ctx.save();
    ctx.beginPath(); ctx.rect(padL, padT, pw, ph); ctx.clip();
    opts.series.forEach((s) => {
      ctx.strokeStyle = s.color; ctx.lineWidth = 1.8; ctx.lineJoin = "round";
      ctx.beginPath();
      let pen = false;
      for (let i = 0; i < ts.length; i++) {
        const v = s.values[i];
        if (!isNum(v) || !isNum(ts[i])) { pen = false; continue; }
        const xx = x(ts[i]), yy = y(v);
        if (pen) ctx.lineTo(xx, yy); else ctx.moveTo(xx, yy);
        pen = true;
      }
      ctx.stroke();
    });
    ctx.restore();

    // legend
    ctx.textAlign = "right"; ctx.textBaseline = "top";
    let lx = padL + pw - 4;
    opts.series.slice().reverse().forEach((s) => {
      if (!s.label) return;
      ctx.fillStyle = s.color;
      ctx.fillText(s.label, lx, padT + 2);
      lx -= ctx.measureText(s.label).width + 14;
    });
  }

  // ------------------------------------------------------------ rendering
  let lastStatus = null;

  function renderStatus(st) {
    lastStatus = st;
    const src = st.source || {};
    const counters = st.counters || {};
    const cfg = st.config || {};
    const hasPackets = isNum(counters.packets) && counters.packets > 0;

    // top bar + banner
    const pill = $("source-pill");
    const banner = $("source-banner");
    if (!src.kind) {
      pill.textContent = "No source"; setClass(pill, "pill", "pill-muted");
    } else {
      const kindName = { live: "Live serial", replay: "Replay", simulation: "Simulation" }[src.kind] || src.kind;
      const state = src.finished ? "finished" : (src.connected ? (src.running ? "running" : "stopped") : (src.running ? "connecting" : "stopped"));
      pill.textContent = kindName + ": " + state;
      setClass(pill, "pill", src.connected && src.running ? "pill-ok" : (src.running ? "pill-warn" : "pill-muted"));
    }
    if (src.kind === "simulation" || src.synthetic) {
      banner.textContent = "SIMULATED DATA - synthetic, not evidence of real-world accuracy";
      setClass(banner, "banner", "banner-sim");
    } else if (src.kind === "replay") {
      banner.textContent = "REPLAY of recorded data - not a live measurement";
      setClass(banner, "banner", "banner-replay");
    } else {
      banner.textContent = "";
      setClass(banner, "banner", "hidden");
    }

    // connection card
    let conn = "No source";
    if (src.kind === "live") conn = src.connected ? "Connected" : (src.running ? "Disconnected (retrying)" : "Stopped");
    else if (src.kind === "replay") conn = src.finished ? "Replay finished" : (src.running ? "Replaying" : "Stopped");
    else if (src.kind) conn = src.running ? "Running" : "Stopped";
    setText("conn-state", conn);
    setText("conn-port", src.port);
    setText("conn-reconnects", src.kind ? src.reconnects : null);
    setText("conn-error", src.engine_error || src.last_error);

    // packet rate card
    setText("rate", hasPackets ? fmt(st.packet_rate_hz, 1, "Hz") : null, NO_DATA);
    setText("cnt-packets", src.kind ? counters.packets : null);
    setText("cnt-lines", src.kind ? counters.lines : null);
    setText("pkt-age", isNum(st.last_packet_age_s) ? st.last_packet_age_s.toFixed(1) + " s ago" : null);

    // signal card
    const rssi = st.rssi || {};
    setText("rssi", isNum(rssi.last) ? rssi.last + " dBm" : null, NO_DATA);
    setText("rssi-stats", isNum(rssi.mean) ? fmt(rssi.mean, 1) + " / " + (fmt(rssi.std, 1) || "-") + " dB" : null);
    setText("noise-floor", isNum(st.noise_floor) ? st.noise_floor + " dBm" : null);
    const motion = st.motion || null;
    setText("mean-amp", motion ? fmt(motion.mean_amplitude, 2) : null);

    // errors card
    setText("malformed", src.kind ? counters.malformed + " malformed" : null, NO_DATA);
    setText("seq-gaps", src.kind ? counters.seq_gaps : null);
    setText("seq-dups", src.kind ? counters.duplicates + " / " + counters.seq_resets : null);
    const reasons = counters.malformed_reasons || {};
    const reasonText = Object.keys(reasons).map((k) => k + ": " + reasons[k]).join(", ");
    setText("malformed-reasons", reasonText || null);

    // quality
    const q = st.quality || {};
    const qb = $("quality-badge");
    if (q.ok === true) { qb.textContent = "Sufficient"; setClass(qb, "badge", "badge-ok"); }
    else if (q.ok === false) { qb.textContent = "Insufficient"; setClass(qb, "badge", "badge-bad"); }
    else { qb.textContent = "No source"; setClass(qb, "badge", "badge-muted"); }
    const ul = $("quality-reasons");
    const items = (q.reasons || []).map((r) => "<li>" + escapeHtml(r) + "</li>").join("");
    if (ul.innerHTML !== items) ul.innerHTML = items;

    // configuration
    setText("cfg-chip", cfg.chip_family ? cfg.chip_family + (cfg.header_family ? " (header: " + cfg.header_family + ")" : "") : null);
    setText("cfg-channel", cfg.channel);
    setText("cfg-secondary", isNum(cfg.secondary_channel) ? ["none", "above", "below"][cfg.secondary_channel] || cfg.secondary_channel : null);
    setText("cfg-bw", isNum(cfg.bandwidth_mhz) ? cfg.bandwidth_mhz + " MHz" : (isNum(cfg.bandwidth) ? "code " + cfg.bandwidth : null));
    setText("cfg-len", cfg.csi_len);
    setText("cfg-nsc", cfg.n_subcarriers);
    setText("cfg-mac", cfg.tx_mac);
    const cal = st.calibration || {};
    setText("cfg-calib", cal.active ? (cal.name || "active") : "none (adaptive reference)");
    const rx = cfg.rx_stats;
    setText("cfg-rxstats", rx ? rx.csi_rx_rate_hz.toFixed(1) + " Hz, total " + rx.csi_rx_total + ", drops " + rx.queue_drops + ", gaps " + rx.seq_gaps + ", up " + Math.round(rx.uptime_ms / 1000) + " s" : null);
    const tx = cfg.tx_stats;
    setText("cfg-txstats", tx ? tx.rate_hz.toFixed(1) + " Hz, ok " + tx.sent_ok + ", fail " + tx.send_fail + ", up " + Math.round(tx.uptime_ms / 1000) + " s" : null);

    // activity
    const act = st.activity || { key: "unknown", label: "Unknown / insufficient data" };
    const badge = $("activity-badge");
    const key = ACTIVITY_KEYS.indexOf(act.key) >= 0 ? act.key : "unknown";
    setClass(badge, "activity", "act-" + key);
    if (badge.textContent !== act.label) badge.textContent = act.label;
    setText("motion-score", motion ? fmt(motion.motion_score, 2) : null, NO_DATA);
    setText("motion-dev", motion ? fmt(motion.baseline_deviation, 2) : null);
    setText("motion-var", motion ? fmt(motion.variance, 4) : null);
    setText("motion-diff", motion ? fmt(motion.diff_energy, 4) : null);
    const th = st.thresholds || {};
    setText("motion-th", isNum(th.movement) ? "movement " + th.movement + ", rapid " + th.rapid + (th.calibrated ? " (calibrated)" : " (uncalibrated)") : null);
  }

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[ch]);
  }

  function renderSeries(se) {
    const th = (se && se.thresholds) || (lastStatus && lastStatus.thresholds) || {};
    const ts = (se && se.ts) || [];
    const base = { ts: ts, tEnd: se ? se.t_end : null, seconds: SERIES_SECONDS };
    drawLineChart($("chart-amp"), Object.assign({}, base, {
      series: [{ values: (se && se.mean_amplitude) || [], color: COLORS.accent, label: "mean |CSI|" }],
      digits: 1, minRange: 1,
    }));
    drawLineChart($("chart-motion"), Object.assign({}, base, {
      series: [{ values: (se && se.motion) || [], color: COLORS.ok, label: "motion score" }],
      thresholds: [
        { value: th.movement, color: COLORS.accent, label: "movement" },
        { value: th.rapid, color: COLORS.warn, label: "rapid" },
      ],
      digits: 1, minRange: 1, zeroBased: true,
    }));
    drawLineChart($("chart-dev"), Object.assign({}, base, {
      series: [{ values: (se && se.baseline_deviation) || [], color: COLORS.violet, label: "deviation (z)" }],
      digits: 1, minRange: 0.5, zeroBased: true,
    }));
    drawLineChart($("chart-rssi"), Object.assign({}, base, {
      series: [{ values: (se && se.rssi) || [], color: COLORS.warn, label: "RSSI dBm" }],
      digits: 0, minRange: 4,
    }));
  }

  // ------------------------------------------------------------ polling
  let lastSeries = null, lastHeat = null;

  async function tick() {
    const state = $("server-state");
    try {
      const results = await Promise.all([
        api("/api/status"),
        api("/api/series?seconds=" + SERIES_SECONDS),
        api("/api/heatmap?n=" + HEATMAP_ROWS),
      ]);
      renderStatus(results[0]);
      lastSeries = results[1]; lastHeat = results[2];
      renderSeries(lastSeries);
      drawHeatmap(lastHeat);
      state.textContent = "Backend OK"; setClass(state, "pill", "pill-ok");
    } catch (e) {
      state.textContent = "Backend unreachable: " + (e && e.message ? e.message : e);
      setClass(state, "pill", "pill-bad");
    } finally {
      setTimeout(tick, POLL_MS);
    }
  }

  // ------------------------------------------------------------ controls
  async function loadPorts() {
    const sel = $("port-select");
    try {
      const res = await api("/api/ports");
      const prev = sel.value;
      sel.innerHTML = "";
      sel.appendChild(new Option("auto (detect receiver)", "auto"));
      (res.ports || []).forEach((p) => {
        const tag = p.likely_esp32 ? "likely ESP32" : (p.excluded ? "system port" : "other");
        const opt = new Option(p.device + "  [" + tag + (p.description ? ", " + p.description : "") + "]", p.device);
        opt.disabled = !!p.excluded;
        sel.appendChild(opt);
      });
      if ([].some.call(sel.options, (o) => o.value === prev)) sel.value = prev;
      const n = (res.ports || []).filter((p) => p.likely_esp32 && !p.excluded).length;
      showMessage(res.error ? res.error : (n ? n + " likely ESP32 port(s) found." : "No likely ESP32 port found. Check the USB cable."), !!res.error);
    } catch (e) {
      showMessage("Could not list ports: " + e.message, true);
    }
  }

  async function loadReplayFiles() {
    const sel = $("replay-select");
    try {
      const res = await api("/api/replay_files");
      const prev = sel.value;
      sel.innerHTML = "";
      const files = res.files || [];
      if (!files.length) sel.appendChild(new Option("(no files found)", ""));
      files.forEach((f) => sel.appendChild(new Option(f.path + (f.group === "fixtures" ? "  [format fixture]" : ""), f.path)));
      if ([].some.call(sel.options, (o) => o.value === prev)) sel.value = prev;
    } catch (e) {
      showMessage("Could not list replay files: " + e.message, true);
    }
  }

  async function withButton(btn, fn) {
    btn.disabled = true;
    try { await fn(); } finally { btn.disabled = false; }
  }

  function selectTab(which) {
    ["serial", "replay"].forEach((name) => {
      const tab = $("tab-" + name), panel = $("panel-" + name);
      const on = name === which;
      tab.classList.toggle("active", on);
      tab.setAttribute("aria-selected", on ? "true" : "false");
      panel.classList.toggle("hidden", !on);
    });
  }

  function bindControls() {
    $("tab-serial").addEventListener("click", () => selectTab("serial"));
    $("tab-replay").addEventListener("click", () => selectTab("replay"));
    $("ports-refresh").addEventListener("click", loadPorts);
    $("replay-refresh").addEventListener("click", loadReplayFiles);

    $("serial-connect").addEventListener("click", (ev) => withButton(ev.currentTarget, async () => {
      const baud = parseInt($("baud-input").value, 10);
      if (!(baud >= 9600 && baud <= 3000000)) { showMessage("Baud must be between 9600 and 3000000.", true); return; }
      try {
        await postJSON("/api/source", { kind: "serial", port: $("port-select").value, baud: baud });
        showMessage("Opening " + $("port-select").value + " (read-only)...", false);
      } catch (e) { showMessage("Connect failed: " + e.message, true); }
    }));

    $("replay-start").addEventListener("click", (ev) => withButton(ev.currentTarget, async () => {
      const path = $("replay-select").value;
      if (!path) { showMessage("Choose a recording first.", true); return; }
      try {
        await postJSON("/api/source", {
          kind: "replay", path: path, speed: parseFloat($("replay-speed").value), loop: $("replay-loop").checked,
        });
        showMessage("Replaying " + path, false);
      } catch (e) { showMessage("Replay failed: " + e.message, true); }
    }));

    $("source-stop").addEventListener("click", (ev) => withButton(ev.currentTarget, async () => {
      try { await postJSON("/api/stop", {}); showMessage("Source stopped.", false); }
      catch (e) { showMessage("Stop failed: " + e.message, true); }
    }));

    window.addEventListener("resize", () => {
      if (lastSeries) renderSeries(lastSeries);
      if (lastHeat) drawHeatmap(lastHeat);
    });
  }

  document.addEventListener("DOMContentLoaded", () => {
    drawLegend();
    bindControls();
    loadPorts();
    loadReplayFiles();
    tick();
  });
})();

"""Test-only helpers that build CSI_DATA lines in the official format from
numpy amplitude arrays. These are generated test signals, not hardware data."""

from __future__ import annotations

import numpy as np

from backend.csi_parser import LLTF_SUBCARRIERS, VALID_LLTF_INDICES, parse_line

TX_MAC = "1a:00:00:00:00:00"


def classic_line(valid_amps, seq: int = 0, rssi: int = -40, first_word: int = 0, ts_us: int = 0) -> str:
    """Classic 25-field line whose 52 valid LLTF subcarriers have ``valid_amps``
    (real part = amplitude, imag = 0; other subcarriers 0)."""
    amps = np.zeros(LLTF_SUBCARRIERS)
    amps[VALID_LLTF_INDICES] = np.asarray(valid_amps, dtype=float)
    raw = []
    for a in amps:
        raw += [0, int(round(a))]  # [imag, real]
    data = ",".join(str(v) for v in raw)
    return (f"CSI_DATA,{seq},{TX_MAC},{rssi},11,1,0,1,0,1,0,0,0,0,-93,0,11,2,{ts_us},0,67,0,"
            f"{len(raw)},{first_word},\"[{data}]\"")


def c5c6_line(amps, seq: int = 0, rssi: int = -40, ts_us: int = 0) -> str:
    raw = []
    for a in np.asarray(amps, dtype=float):
        raw += [0, int(round(a))]
    data = ",".join(str(v) for v in raw)
    return f"CSI_DATA,{seq},{TX_MAC},{rssi},11,-96,32,4,11,{ts_us},67,0,{len(raw)},0,\"[{data}]\""


def classic_packet(valid_amps, ts: float, seq: int = 0, **kw):
    return parse_line(classic_line(valid_amps, seq=seq, **kw), host_ts=ts)


def c5c6_packet(amps, ts: float, seq: int = 0, **kw):
    return parse_line(c5c6_line(amps, seq=seq, **kw), host_ts=ts)


def base_profile(n: int = 52, level: float = 40.0) -> np.ndarray:
    """Static multipath-like profile (deterministic)."""
    k = np.arange(n)
    return level * (1.0 + 0.3 * np.sin(k / 5.0))


def stream(n_packets: int, rate_hz: float = 100.0, t0: float = 1000.0, noise: float = 0.0,
           perturb: float = 0.0, perturb_hz: float = 1.5, seed: int = 0, profile=None):
    """Yield (ts, valid_amps) for a generated stream. ``perturb`` adds a
    subcarrier-dependent time-varying multipath term (relative amplitude)."""
    rng = np.random.default_rng(seed)
    prof = base_profile() if profile is None else np.asarray(profile, dtype=float)
    phases = np.linspace(0, 3 * np.pi, prof.size)
    for i in range(n_packets):
        t = t0 + i / rate_hz
        amps = prof.copy()
        if perturb:
            amps = amps * (1.0 + perturb * np.sin(2 * np.pi * perturb_hz * (t - t0) + phases))
        if noise:
            amps = amps + rng.normal(0.0, noise, prof.size)
        yield t, np.clip(amps, 1.0, None)

